import React, { useEffect, useState, useContext } from "react";
import { useParams } from "react-router-dom";
import API from "../services/api";
import { CartContext } from "../context/CartContext";

export default function ProductDetail() {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [main, setMain] = useState(null);
  const [size, setSize] = useState(null);
  const [color, setColor] = useState(null);
  const { addToCart } = useContext(CartContext);

  useEffect(()=> {
    API.get(`/products/${id}`).then(r => {
      setProduct(r.data);
      setMain(r.data.images?.[0] || "/images/placeholder.png");
      setSize(r.data.sizes?.[0] || null);
      setColor(r.data.colors?.[0] || null);
    }).catch(()=>{});
  }, [id]);

  if (!product) return <div className="container">Loading...</div>;

  const price = product.discount_price || product.price;
  const old = product.discount_price ? product.price : null;

  return (
    <div className="container product-detail">
      <div className="gallery">
        <div>
          <img src={main} alt={product.name} />
        </div>
        <div className="thumbs">
          {(product.images || [main]).map((src, i) => (
            <div key={i} className="thumb" onClick={()=> setMain(src)}>
              <img src={src} alt="" style={{ width:"100%", height:"100%", objectFit:"cover" }} />
            </div>
          ))}
        </div>
      </div>

      <div className="product-info">
        <h2>{product.name}</h2>
        <div style={{ display:"flex", gap:12, alignItems:"center" }}>
          <div className="price">₹{price}</div>
          {old && <div className="old">₹{old}</div>}
          <div className="rating">{Number(product.rating || 0).toFixed(1)}</div>
        </div>

        <p style={{ color:"var(--muted)" }}>{product.description}</p>

        {product.sizes?.length > 0 && (
          <div className="kv">
            <strong>Size:</strong>
            {product.sizes.map(s => (
              <button key={s} className={`icon-btn`} onClick={()=> setSize(s)} style={{ background: size === s ? "var(--primary)" : "#fff", color: size === s ? "#fff" : "var(--accent)" }}>{s}</button>
            ))}
          </div>
        )}

        {product.colors?.length > 0 && (
          <div className="kv">
            <strong>Color:</strong>
            {product.colors.map(c => (
              <div key={c} className="thumb" onClick={()=> setColor(c)} style={{ width:36, height:36, borderRadius:999, border: color===c ? `2px solid var(--primary)` : "1px solid #eee", background:c }} />
            ))}
          </div>
        )}

        <div style={{ marginTop:12, display:"flex", gap:8 }}>
          <button className="btn" onClick={()=> addToCart({ ...product, id: product.id })}>Add to cart</button>
          <button className="btn secondary">Buy now</button>
        </div>
      </div>
    </div>
  );
}
